<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('student'); $data=db_load(); $search=trim($_GET['search']??''); $location=trim($_GET['location']??''); $rows=[]; foreach($data['internships'] as $i){ if(($i['status']??'Open')!=='Open') continue; $c=db_company($data,(int)$i['company_id']); if(!$c) continue; $hay=strtolower($i['title'].' '.$i['description'].' '.$c['company_name']); if($search!=='' && strpos($hay,strtolower($search))===false) continue; if($location!=='' && stripos($i['location'],$location)===false) continue; $i['company_name']=$c['company_name']; $rows[]=$i; } db_sort_newest($rows); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Internships · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'student_nav.php'; ?><main class="dashboard"><div class="page-heading"><div><p class="eyebrow">OPPORTUNITIES</p><h1>Find your next role.</h1><p>Search open internships by role, company or location.</p></div></div><form class="search-bar" method="GET"><input name="search" value="<?=e($search)?>" placeholder="Role, company or keyword"><input name="location" value="<?=e($location)?>" placeholder="Location"><button class="btn primary" type="submit">Search</button></form><div class="internship-grid"><?php if(!$rows): ?><div class="table-card empty">No matching internships found. Try another search.</div><?php else: foreach($rows as $row): ?><article class="internship-card"><span class="status open">Open</span><h2><?=e($row['title'])?></h2><h4><?=e($row['company_name'])?></h4><p><?=e($row['description'])?></p><div class="tags"><span><?=e($row['location'])?></span><?php if($row['skills']): ?><span><?=e($row['skills'])?></span><?php endif; ?><?php if($row['duration']): ?><span><?=e($row['duration'])?></span><?php endif; ?></div><a class="btn primary" href="apply.php?id=<?=$row['id']?>">View & apply</a></article><?php endforeach; endif; ?></div></main></body></html>
